<template>
  <v-dialog
    persistent
    :model-value="modelValue"
    max-width="500"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div class="sv-card">
      <div class="sv-head">
        <div class="sv-icon"><v-icon icon="mdi-content-save-outline" size="22" /></div>
        <div class="sv-titles">
          <div class="sv-title">{{ editView ? "Edit View" : "Save Current View" }}</div>
          <div class="sv-sub">Name this dashboard so you can open it later</div>
        </div>
        <button class="sv-close" aria-label="Close" @click="close">
          <v-icon icon="mdi-close" size="18" />
        </button>
      </div>

      <div class="sv-body">
        <v-text-field
          v-model="name"
          placeholder="Enter view name"
          variant="outlined"
          density="comfortable"
          hide-details
          maxlength="100"
          @keyup.enter="save"
        >
          <template #label>View Name <span class="sv-req">*</span></template>
        </v-text-field>

        <v-text-field
          v-model="type"
          label="Type"
          variant="outlined"
          density="comfortable"
          hide-details
          disabled
        />

        <v-textarea
          v-model="desc"
          label="Description (optional)"
          placeholder="Enter description"
          variant="outlined"
          density="comfortable"
          hide-details
          rows="3"
          maxlength="500"
        />
      </div>

      <div class="sv-actions">
        <button class="sv-btn sv-cancel" @click="close">Cancel</button>
        <button class="sv-btn sv-go" :disabled="!name.trim()" @click="save">
          {{ editView ? "Update" : "Save" }}
        </button>
      </div>
    </div>
  </v-dialog>
</template>

<script>
import { useDashboardStore } from "@/store/dashboardStore";

export default {
  name: "SaveViewDialog",
  setup() {
    return { store: useDashboardStore() };
  },
  props: {
    modelValue: Boolean,
    editView: Object,
  },

  emits: ["update:modelValue", "save"],

  data() {
    return {
      name: "",
      type: this.store.type,
      desc: "",
    };
  },

  watch: {
    modelValue(value) {
      if (!value) return;

      if (this.editView) {
        this.name = this.editView.name || "";
        this.type = this.editView.type || this.store.type;
        this.desc = this.editView.desc || "";
      } else {
        this.name = "";
        this.type = this.store.type;
        this.desc = "";
      }
    },
  },

  methods: {
    close() {
      this.$emit("update:modelValue", false);
    },

    save() {
      if (!this.name.trim()) return;

      this.$emit("save", {
        name: this.name.trim(),
        type: this.type,
        desc: this.desc,
      });

      this.close();
    },
  },
};
</script>

<style scoped>
.sv-card {
  background: #fff;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.18);
  animation: sv-pop 0.18s ease-out;
}
@keyframes sv-pop {
  from { opacity: 0; transform: scale(0.96) translateY(6px); }
  to { opacity: 1; transform: none; }
}

.sv-head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px 20px 18px 24px;
  border-bottom: 1px solid #eee;
}
.sv-icon {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: rgba(15, 98, 254, 0.08);
  color: #0f62fe;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}
.sv-titles { flex: 1; min-width: 0; }
.sv-title { font-size: 17px; font-weight: 700; color: #1a1a1a; }
.sv-sub { font-size: 13px; color: #666; margin-top: 2px; }
.sv-close {
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: #777;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.sv-close:hover { background: #f0f2f5; color: #222; }

.sv-body {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 22px 24px;
}
.sv-req { color: #da1e28; font-weight: 700; }

.sv-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 14px 24px;
  background: #fafafa;
  border-top: 1px solid #eee;
}
.sv-btn {
  height: 38px;
  min-width: 88px;
  padding: 0 20px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, box-shadow 0.15s, transform 0.1s;
}
.sv-cancel { background: #fff; color: #444; border: 1px solid #ccc; }
.sv-cancel:hover { background: #f5f7fa; border-color: #999; }
.sv-go { background: #0f62fe; color: #fff; border: 1px solid #0f62fe; }
.sv-go:hover:not(:disabled) { background: #0a4fd1; box-shadow: 0 2px 8px rgba(15, 98, 254, 0.35); }
.sv-go:disabled { background: #b9c9e8; border-color: #b9c9e8; cursor: not-allowed; }
.sv-btn:active:not(:disabled) { transform: scale(0.97); }

@media (max-width: 480px) {
  .sv-actions { flex-direction: column-reverse; }
  .sv-btn { width: 100%; }
}
</style>