const DAY = 86400000;
const day = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d)
    ? null
    : new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
};
const diff = (a, b) => Math.round((a - b) / DAY);
const isDone = (t) =>
  !!day(t.actualFinishDate) || /^complete/i.test(t.state || "");
const deadline = (t) => day(t.dueDate) ?? day(t.estimatedFinishDate);

function upcoming(t, today, n) {
  const es = day(t.estimatedStartDate);
  if (es == null || day(t.actualStartDate) != null) return null;
  return es >= today && es <= today + n * DAY ? diff(es, today) : null;
}

// each rule returns the number of days to show, or null when the task doesn't match
const RULES = {
  overdue: (t, today) => {
    const dl = deadline(t);
    return !isDone(t) && dl != null && dl < today ? diff(today, dl) : null;
  },
  completedLate: (t) => {
    const dl = deadline(t);
    const af = day(t.actualFinishDate);
    return isDone(t) && af != null && dl != null && af > dl
      ? diff(af, dl)
      : null;
  },
  lateStart: (t, today) => {
    const es = day(t.estimatedStartDate);
    const as = day(t.actualStartDate);
    if (es == null) return null;
    if (as != null) return as > es ? diff(as, es) : null; // started after the plan
    return !isDone(t) && es < today ? diff(today, es) : null; // planned start passed, not started
  },
  next7: (t, today) => upcoming(t, today, 7),
  next14: (t, today) => upcoming(t, today, 14),
};

export function applySchedule(tasks, filterId, now = Date.now()) {
  if (filterId === "all") {
    const key = (t) => day(t.estimatedStartDate) ?? 8.64e15; // undated items go last
    return tasks
      .map((t) => ({ ...t, days: null }))
      .sort((a, b) => key(a) - key(b));
  }
  const rule = RULES[filterId];
  const today = day(now);
  if (!rule) return [];
  const rows = tasks
    .map((t) => ({ ...t, days: rule(t, today) }))
    .filter((t) => t.days != null);
  const asc = filterId === "next7" || filterId === "next14";
  return rows.sort((a, b) => (asc ? a.days - b.days : b.days - a.days));
}
