<template>
  <div class="tl-wrap">
    <div class="tl">
      <div class="tl-head">
        <div class="tl-label">{{ text.name }}</div>
        <div class="tl-area">
          <span v-for="k in ticks" :key="k.pos" class="tl-tick" :style="{ left: k.pos + '%' }">{{ k.label }}</span>
        </div>
      </div>

      <div v-for="it in items" :key="it.r.id" class="tl-row">
        <div class="tl-label" :title="it.r.title">
          <div class="tl-name">{{ it.r.title }}</div>
          <div class="tl-sub">{{ it.r.objType }}</div>
        </div>
        <div class="tl-area">
          <span v-for="k in ticks" :key="k.pos" class="tl-grid" :style="{ left: k.pos + '%' }" />
          <span v-if="todayPos != null" class="tl-today" :style="{ left: todayPos + '%' }" />
          <span v-if="it.plan" class="tl-plan" :style="it.plan" :title="it.planTitle" />
          <span v-if="it.act" class="tl-act" :style="it.act" :title="it.actTitle" />
        </div>
      </div>
    </div>

    <div class="tl-legend">
      <span><i class="tl-key tl-key--plan" />{{ text.planned }}</span>
      <span v-for="l in legend" :key="l.label"><i class="tl-key" :style="{ background: l.c }" />{{ l.label }}</span>
      <span><i class="tl-key tl-key--today" />{{ text.today }}</span>
    </div>
  </div>
</template>

<script>
import { SCHEDULE_TEXT } from "@/utils/uiText";
import { SCHEDULE_HEALTH_COLORS as C } from "@/utils/dashboardData";

const DAY = 86400000;
const ms = (v) => {
  const t = v ? new Date(v).getTime() : NaN;
  return isNaN(t) ? null : t;
};
const fmt = (v) => (v == null ? "–" : new Date(v).toLocaleDateString());

export default {
  name: "ScheduleTimeline",
  props: { rows: { type: Array, required: true } },
  data: () => ({ text: SCHEDULE_TEXT }),
  computed: {
    legend() {
      return [
        { label: this.text.onTime, c: C.onTime },
        { label: this.text.late, c: C.late },
        { label: this.text.overdue, c: C.overdue },
        { label: this.text.open, c: C.open },
      ];
    },
    bounds() {
      const vals = [Date.now()];
      this.rows.forEach((r) => {
        const s = this.span(r);
        [s.ps, s.pe, s.as, s.ae].forEach((v) => v != null && vals.push(v));
      });
      const lo = Math.min(...vals);
      const hi = Math.max(...vals);
      const pad = Math.max(3 * DAY, (hi - lo) * 0.04);
      return { lo: lo - pad, hi: hi + pad };
    },
    todayPos() {
      const p = this.pos(Date.now());
      return p >= 0 && p <= 100 ? p : null;
    },
    ticks() {
      const { lo, hi } = this.bounds;
      const d = new Date(lo);
      d.setDate(1);
      d.setHours(0, 0, 0, 0);
      const months = [];
      while (d.getTime() <= hi) {
        if (d.getTime() >= lo) months.push(new Date(d));
        d.setMonth(d.getMonth() + 1);
      }
      const step = Math.max(1, Math.ceil(months.length / 10));
      return months
        .filter((_, i) => i % step === 0)
        .map((m) => ({
          pos: this.pos(m.getTime()),
          label: m.toLocaleDateString(undefined, { month: "short", year: "2-digit" }),
        }));
    },
    items() {
      const today = new Date().setHours(0, 0, 0, 0);
      return this.rows.map((r) => {
        const s = this.span(r);
        const actEnd = s.ae ?? (s.as != null ? Math.max(today, s.as) : null);
        let color = C.open;
        if (s.ae != null) color = s.pe != null && s.ae > s.pe ? C.late : C.onTime;
        else if (s.pe != null && s.pe < today) color = C.overdue;

        const act = this.bar(s.as, actEnd);
        return {
          r,
          plan: this.bar(s.ps, s.pe),
          planTitle: `${this.text.planned}: ${fmt(s.ps)} → ${fmt(s.pe)}`,
          act: act && { ...act, background: color },
          actTitle: `${fmt(s.as)} → ${fmt(s.ae)}`,
        };
      });
    },
  },
  methods: {
    span(r) {
      return {
        ps: ms(r.estimatedStartDate),
        pe: ms(r.estimatedFinishDate) ?? ms(r.dueDate),
        as: ms(r.actualStartDate),
        ae: ms(r.actualFinishDate),
      };
    },
    pos(v) {
      const { lo, hi } = this.bounds;
      return ((v - lo) / (hi - lo)) * 100;
    },
    bar(a, b) {
      if (a == null && b == null) return null;
      a = a ?? b;
      b = Math.max(b ?? a, a);
      return { left: this.pos(a) + "%", width: Math.max(this.pos(b + DAY) - this.pos(a), 0.4) + "%" };
    },
  },
};
</script>

<style scoped>
.tl-wrap { border: 1px solid #eee; border-radius: 10px; overflow: hidden; }
.tl-head, .tl-row { display: grid; grid-template-columns: 260px 1fr; }
.tl-head { background: #fafafa; border-bottom: 1px solid #eee; }
.tl-row { border-bottom: 1px solid #f3f3f3; }
.tl-row:hover { background: #f8faff; }
.tl-label { padding: 8px 12px; min-width: 0; font-size: 12px; font-weight: 600; color: #666; display: flex; flex-direction: column; justify-content: center; border-right: 1px solid #eee; }
.tl-head .tl-label { height: 28px; }
.tl-name { font-size: 13px; font-weight: 600; color: #1a1a1a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tl-sub { font-size: 11px; color: #999; font-weight: 400; }
.tl-area { position: relative; height: 44px; }
.tl-head .tl-area { height: 28px; }
.tl-tick { position: absolute; top: 7px; transform: translateX(-50%); font-size: 11px; color: #777; white-space: nowrap; }
.tl-grid { position: absolute; top: 0; bottom: 0; width: 1px; background: #f0f0f0; }
.tl-today { position: absolute; top: 0; bottom: 0; width: 2px; background: #da1e28; opacity: 0.55; z-index: 2; }
.tl-plan, .tl-act { position: absolute; height: 8px; border-radius: 4px; min-width: 6px; }
.tl-plan { top: 11px; background: #cfd8ea; }
.tl-act { top: 24px; z-index: 1; }
.tl-legend { display: flex; flex-wrap: wrap; gap: 6px 18px; padding: 10px 14px; font-size: 12px; color: #666; background: #fafafa; border-top: 1px solid #eee; }
.tl-legend span { display: flex; align-items: center; gap: 6px; }
.tl-key { width: 12px; height: 8px; border-radius: 3px; display: inline-block; }
.tl-key--plan { background: #cfd8ea; }
.tl-key--today { width: 2px; height: 12px; background: #da1e28; opacity: 0.55; }
</style>