<template>
    <div class="sc-wrap">
        <!-- fixed top: header, project, filter cards -->
        <div class="sc-fixed">
            <div class="sc-head">
                <div class="sc-icon"><v-icon icon="mdi-calendar-clock-outline" size="22" /></div>
                <div class="sc-titles">
                    <h2 class="sc-title">{{ text.title }}</h2>
                    <div class="sc-sub">{{ text.subtitle }}</div>
                </div>

                <v-autocomplete v-model="project" class="sc-project" :items="projects" :loading="loadingProjects"
                    prepend-inner-icon="mdi-briefcase-outline" clearable variant="outlined" density="compact"
                    hide-details>
                    <template #label>{{ text.project }} <span class="sc-req">*</span></template>
                    <template #no-data>
                        <div class="sc-nodata">
                            {{ text.noProjects }}
                            <a href="#" @click.prevent="loadProjects">{{ text.retry }}</a>
                        </div>
                    </template>
                </v-autocomplete>

                <div v-if="loading || loadingProjects" class="sc-status">
                    <v-progress-circular indeterminate size="14" width="2" />
                    <span v-if="loading">{{ text.loadedLabel }} {{ tasks.length }} {{ text.of }} {{ total || "…"
                        }}</span>
                    <span v-else>{{ text.loadingProjects }}</span>
                </div>
                <button v-if="project" class="sc-refresh" :disabled="loading" title="Reload" @click="loadTasks">
                    <v-icon icon="mdi-refresh" size="18" :class="{ spin: loading }" />
                </button>
            </div>

            <div v-if="project" class="sc-tiles">
                <button v-for="f in filters" :key="f.id" class="sc-tile" :class="{ active: filterId === f.id }"
                    :style="{ '--c': f.color }" @click="filterId = f.id">
                    <span class="sc-tile-icon"><v-icon :icon="f.icon" size="20" /></span>
                    <span class="sc-tile-body">
                        <span class="sc-tile-n">{{ loaded || tasks.length ? counts[f.id] : "–" }}</span>
                        <span class="sc-tile-l">{{ f.short }}</span>
                    </span>
                </button>
            </div>

            <div v-if="loading" class="sc-bar" :class="{ 'sc-bar--wait': !total }">
                <span :style="{ width: pct + '%' }" />
            </div>
        </div>

        <div class="sc-panel sc-results">
            <div v-if="!project" class="sc-state">
                <v-icon icon="mdi-briefcase-search-outline" size="44" />
                <div class="sc-state-t">{{ text.pickProject }}</div>
                <div class="sc-state-s">{{ text.pickProjectHint }}</div>
            </div>

            <div v-else-if="loading && !tasks.length" class="sc-state">
                <v-progress-circular indeterminate size="30" width="3" color="primary" />
                <div class="sc-state-s">{{ text.loading }}</div>
                <div v-if="total" class="sc-state-s">{{ text.loadedLabel }} 0 {{ text.of }} {{ total }}</div>
            </div>

            <template v-else-if="loaded || tasks.length">
                <div v-if="!tasks.length" class="sc-state">
                    <v-icon icon="mdi-clipboard-text-off-outline" size="44" />
                    <div class="sc-state-s">{{ text.noItems }}</div>
                </div>

                <template v-else>
                    <!-- <ScheduleSummary :tasks="tasks" :counts="counts" /> -->

                    <div class="sc-summary">
                        <span class="sc-dot" :style="{ background: currentFilter.color }" />
                        <b>{{ shown.length }}</b> {{ text.of }} {{ tasks.length }} {{ text.items }}
                        <span class="sc-fname">{{ currentFilter.label }}</span>

                        <div class="sc-tools">
                            <select v-for="k in colKeys" :key="k" v-model="colFilter[k]" class="sc-select">
                                <option value="">{{ k === "objType" ? text.allTypes : text.allStates }}</option>
                                <option v-for="o in colOptions[k]" :key="o" :value="o">{{ o }}</option>
                            </select>
                            <div class="sc-toggle">
                                <button :class="{ on: view === 'table' }" @click="view = 'table'">
                                    <v-icon icon="mdi-table" size="16" /> {{ text.viewTable }}
                                </button>
                                <button :class="{ on: view === 'timeline' }" @click="view = 'timeline'">
                                    <v-icon icon="mdi-chart-gantt" size="16" /> {{ text.viewTimeline }}
                                </button>
                            </div>
                        </div>
                    </div>

                    <div v-if="!shown.length" class="sc-state sc-state--compact">
                        <v-icon icon="mdi-check-circle-outline" size="40" />
                        <div class="sc-state-t">{{ text.empty }}</div>
                        <div class="sc-state-s">{{ text.emptyHint }}</div>
                    </div>

                    <template v-else>
                        <div v-if="view === 'table'" class="sc-table-wrap">
                            <table class="sc-table">
                                <thead>
                                    <tr>
                                        <th>{{ text.name }}</th>
                                        <th>{{ text.type }}</th>
                                        <th>{{ text.state }}</th>
                                        <th v-for="c in dateColumns" :key="c.key">{{ c.label }}</th>
                                        <th class="sc-r">{{ currentFilter.daysLabel }}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr v-for="r in pageRows" :key="r.id">
                                        <td class="sc-main">
                                            <div class="sc-name" :title="r.title">{{ r.title }}</div>
                                            <div class="sc-id">{{ r.name }}</div>
                                        </td>
                                        <td><span class="sc-type">{{ r.objType }}</span></td>
                                        <td>
                                            <span class="sc-chip" :style="{ '--c': stateColor(r.state) }">{{ r.state ||
                                                "–" }}</span>
                                        </td>
                                        <td v-for="c in dateColumns" :key="c.key" class="sc-date">
                                            {{ c.formatter(r[c.key]) || "–" }}
                                        </td>
                                        <td class="sc-r">
                                            <span v-if="r.days != null" class="sc-badge"
                                                :style="{ '--c': currentFilter.color }">{{ r.days }} d</span>
                                            <span v-else class="sc-date">–</span>
                                        </td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>
                        <ScheduleTimeline v-else :rows="pageRows" />

                        <div class="sc-pager">
                            <div class="sc-pager-size">
                                {{ text.rowsPerPage }}
                                <select v-model.number="pageSize" class="sc-select">
                                    <option v-for="n in pageSizes" :key="n" :value="n">{{ n }}</option>
                                </select>
                                <span class="sc-range">{{ rangeFrom }}–{{ rangeTo }} {{ text.of }} {{ shown.length
                                    }}</span>
                            </div>
                            <v-pagination v-model="page" :length="pages" :total-visible="5" density="comfortable"
                                rounded="lg" />
                        </div>
                    </template>
                </template>
            </template>
        </div>
    </div>
</template>

<script>
import scheduleApi from "@/services/scheduleApi";
// import ScheduleSummary from "@/components/ScheduleSummary.vue";
import ScheduleTimeline from "@/components/ScheduleTimeline.vue";
import { applySchedule } from "@/utils/scheduleRules";
import {
    SCHEDULE_FILTERS,
    SCHEDULE_DATE_COLUMNS,
    DEFAULT_SCHEDULE_FILTER,
    SCHEDULE_STATE_COLORS,
    SCHEDULE_STATE_DEFAULT_COLOR,
} from "@/utils/dashboardData";
import { SCHEDULE_TEXT } from "@/utils/uiText";
import { toastBus } from "@/components/common/toastBus";

const PAGE_SIZES = [10, 25, 50, 100];

export default {
    name: "ScheduleView",
    components: { ScheduleTimeline },
    data() {
        return {
            text: SCHEDULE_TEXT,
            filters: SCHEDULE_FILTERS,
            dateColumns: SCHEDULE_DATE_COLUMNS,
            pageSizes: PAGE_SIZES,
            projects: [],
            project: null,
            filterId: DEFAULT_SCHEDULE_FILTER,
            tasks: [],
            total: 0,
            page: 1,
            pageSize: 25,
            view: "table",
            colKeys: ["objType", "state"],
            colFilter: { objType: "", state: "" },
            loadingProjects: false,
            loading: false,
            loaded: false,
            req: 0,
        };
    },
    computed: {
        currentFilter() {
            return this.filters.find((f) => f.id === this.filterId);
        },
        shown() {
            const c = this.colFilter;
            return applySchedule(this.tasks, this.filterId).filter(
                (r) => (!c.objType || r.objType === c.objType) && (!c.state || r.state === c.state),
            );
        },
        colOptions() {
            const o = {};
            this.colKeys.forEach((k) => {
                o[k] = [...new Set(this.tasks.map((t) => t[k]).filter(Boolean))].sort();
            });
            return o;
        },
        counts() {
            return Object.fromEntries(
                this.filters.map((f) => [f.id, applySchedule(this.tasks, f.id).length]),
            );
        },
        pct() {
            return this.total ? Math.min(100, Math.round((this.tasks.length / this.total) * 100)) : 0;
        },
        pages() {
            return Math.max(1, Math.ceil(this.shown.length / this.pageSize));
        },
        pageRows() {
            const s = (this.page - 1) * this.pageSize;
            return this.shown.slice(s, s + this.pageSize);
        },
        rangeFrom() {
            return this.shown.length ? (this.page - 1) * this.pageSize + 1 : 0;
        },
        rangeTo() {
            return Math.min(this.page * this.pageSize, this.shown.length);
        },
    },
    watch: {
        project() {
            this.loadTasks();
        },
        filterId() {
            this.page = 1;
        },
        pageSize() {
            this.page = 1;
        },
        colFilter: {
            deep: true,
            handler() {
                this.page = 1;
            },
        },
        pages(n) {
            if (this.page > n) this.page = n; // rows were added/removed
        },
    },
    mounted() {
        this.loadProjects();
    },
    methods: {
        stateColor(state) {
            return SCHEDULE_STATE_COLORS[String(state || "").toLowerCase()] || SCHEDULE_STATE_DEFAULT_COLOR;
        },
        async loadProjects() {
            this.loadingProjects = true;
            this.projects = [];
            try {
                await scheduleApi.fetchProjects((names) => {
                    this.projects = [...this.projects, ...names].sort((a, b) => a.localeCompare(b));
                });
            } catch (e) {
                toastBus.emit(this.text.projectsFailed, "error");
            } finally {
                this.loadingProjects = false;
            }
        },
        async loadTasks() {
            const id = ++this.req; // always invalidates any request still in flight
            this.tasks = [];
            this.total = 0;
            this.page = 1;
            this.loaded = false;
            this.loading = false;
            this.colFilter = { objType: "", state: "" };
            if (!this.project) return;
            this.loading = true;
            try {
                await scheduleApi.fetchTasks(
                    this.project,
                    (rows) => {
                        if (id === this.req) this.tasks = [...this.tasks, ...rows];
                    },
                    (n) => {
                        if (id === this.req) this.total += n;
                    },
                );
                if (id === this.req) this.loaded = true;
            } catch (e) {
                if (id === this.req) toastBus.emit(this.text.loadFailed, "error");
            } finally {
                if (id === this.req) this.loading = false;
            }
        },
    },
};
</script>

